//! Differential reads against stores built by the real SAGE code
//! (`tests/fixtures/oracle/*`, generated by `scripts/oracle/build-fixtures.ts`).
//!
//! Each fixture database is copied to a temp directory and opened read-only;
//! the committed bytes are never touched. Oracle placeholders (`<id:x>`,
//! `<volatile>`, `<ulid:n>`) are matched through the fixture's `ids.json`.
//!
//! Known, documented gap: SAGE re-ranks multi-token queries with
//! `hybridRerankMemories`; the native slice does not, so for queries with two
//! or more terms only the result SET is compared, not the order.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use serde_json::Value;
use wrongmemory_storage::{SageStore, Verdict, Viewer};

const NOW: &str = "2026-11-01T12:00:00.000Z";

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/oracle")
}

struct Fixture {
    name: String,
    store: SageStore,
    labels: BTreeMap<String, String>,
    queries: Vec<Value>,
    _tmp: tempfile::TempDir,
}

fn load(name: &str) -> Fixture {
    let dir = fixtures_dir().join(name);
    let tmp = tempfile::tempdir().unwrap();
    let db = tmp.path().join("sage.db");
    std::fs::copy(dir.join("sage.db"), &db).unwrap();
    let (store, insp) = SageStore::open(&db, false, None, NOW).unwrap();
    assert!(
        matches!(insp.verdict, Verdict::Compatible),
        "{name}: {:?} {}",
        insp.verdict,
        insp.detail
    );
    let ids: Value =
        serde_json::from_str(&std::fs::read_to_string(dir.join("ids.json")).unwrap()).unwrap();
    let labels = ids["ids"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(label, id)| (id.as_str().unwrap().to_string(), label.clone()))
        .collect();
    let q: Value =
        serde_json::from_str(&std::fs::read_to_string(dir.join("queries.json")).unwrap()).unwrap();
    Fixture {
        name: name.into(),
        store,
        labels,
        queries: q["results"].as_array().unwrap().clone(),
        _tmp: tmp,
    }
}

impl Fixture {
    fn label(&self, id: &str) -> String {
        self.labels
            .get(id)
            .map(|l| format!("<id:{l}>"))
            .unwrap_or_else(|| id.to_string())
    }

    fn real_id(&self, label: &str) -> String {
        self.labels
            .iter()
            .find(|(_, l)| *l == label)
            .map(|(id, _)| id.clone())
            .unwrap_or_else(|| panic!("{}: no id for label {label}", self.name))
    }
}

/// Structural equality where an oracle string placeholder `<...>` matches any
/// string. Our ids are mapped to labels first.
fn same(f: &Fixture, oracle: &Value, ours: &Value, path: &str) -> Result<(), String> {
    match (oracle, ours) {
        (Value::String(o), Value::String(u)) => {
            if o.starts_with('<') && o.ends_with('>') {
                if o.starts_with("<id:") && f.label(u) != *o {
                    return Err(format!("{path}: {o} vs {}", f.label(u)));
                }
                Ok(())
            } else if o == u {
                Ok(())
            } else {
                Err(format!("{path}: {o:?} vs {u:?}"))
            }
        }
        (Value::Object(o), Value::Object(u)) => {
            let keys: BTreeSet<&String> = o.keys().chain(u.keys()).collect();
            for k in keys {
                match (o.get(k), u.get(k)) {
                    (Some(a), Some(b)) => same(f, a, b, &format!("{path}.{k}"))?,
                    (a, b) => return Err(format!("{path}.{k}: {a:?} vs {b:?}")),
                }
            }
            Ok(())
        }
        (Value::Array(o), Value::Array(u)) if o.len() == u.len() => {
            for (i, (a, b)) in o.iter().zip(u).enumerate() {
                same(f, a, b, &format!("{path}[{i}]"))?;
            }
            Ok(())
        }
        (Value::Number(o), Value::Number(u)) if o.as_f64() == u.as_f64() => Ok(()),
        (o, u) if o == u => Ok(()),
        (o, u) => Err(format!("{path}: {o} vs {u}")),
    }
}

/// Parse `searchSage("q")`, `searchSage("q", sessionId=x)`, `searchSage("q", limit=n)`.
/// Other option shapes are not covered by the native slice and are skipped.
fn parse_search(name: &str) -> Option<(String, Option<String>, usize)> {
    let inner = name.strip_prefix("searchSage(")?.strip_suffix(')')?;
    let (q, rest) = if let Some(end) = inner.rfind('"') {
        (
            serde_json::from_str::<String>(&inner[..=end]).ok()?,
            &inner[end + 1..],
        )
    } else {
        return None;
    };
    let mut session = None;
    let mut limit = 20;
    for opt in rest.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if let Some(v) = opt.strip_prefix("sessionId=") {
            session = Some(v.to_string());
        } else if let Some(v) = opt.strip_prefix("limit=") {
            limit = v.parse().ok()?;
        } else {
            return None;
        }
    }
    Some((q, session, limit))
}

fn ids_of(f: &Fixture, records: &[Value]) -> Vec<String> {
    records
        .iter()
        .map(|r| {
            let id = r["id"].as_str().unwrap().to_string();
            if id.starts_with('<') {
                id
            } else {
                f.label(&id)
            }
        })
        .collect()
}

#[test]
fn search_matches_oracle() {
    let mut compared = 0;
    let mut report = Vec::new();
    for name in ["basic", "unicode", "corrupt-row", "empty"] {
        let f = load(name);
        for q in &f.queries {
            let qname = q["name"].as_str().unwrap();
            let Some((query, session, limit)) = parse_search(qname) else {
                continue;
            };
            let viewer = Viewer {
                session_id: session,
            };
            let ours = f.store.search(&query, limit, None, None, &viewer).unwrap();
            let ours_ids: Vec<String> = ours.hits.iter().map(|h| f.label(&h.memory.id)).collect();
            let want = ids_of(&f, q["result"]["ok"].as_array().unwrap());
            let multi = wrongmemory_storage::store::fts_prefix_terms(&query).len() >= 2;
            let ok = ours_ids == want;
            let _ = multi;
            report.push(format!(
                "{} {name} {qname}: oracle={want:?} ours={ours_ids:?}",
                if ok { "PASS" } else { "FAIL" }
            ));
            compared += 1;
        }
    }
    let failures: Vec<&String> = report.iter().filter(|l| l.starts_with("FAIL")).collect();
    assert!(compared >= 20, "too few comparable queries: {compared}");
    assert!(
        failures.is_empty(),
        "search parity failures:\n{}",
        report.join("\n")
    );
}

#[test]
fn exact_id_reads_match_oracle_records() {
    let mut compared = 0;
    for name in ["basic", "unicode", "corrupt-row"] {
        let f = load(name);
        for q in &f.queries {
            let qname = q["name"].as_str().unwrap();
            let viewer = Viewer::default();
            if qname == "getSage(each)" {
                for pair in q["result"]["ok"].as_array().unwrap() {
                    let label = pair[0].as_str().unwrap();
                    let oracle = &pair[1];
                    let id = f.real_id(label);
                    // Exact-ID reads in the oracle run with includeAllSessions
                    // semantics only where noted; compare whatever SAGE returned.
                    let session = oracle["ownerSessionId"].as_str().map(str::to_string);
                    let ours = f
                        .store
                        .get(
                            &id,
                            &Viewer {
                                session_id: session,
                            },
                        )
                        .unwrap();
                    match (oracle.is_null(), ours) {
                        (true, None) => {}
                        (false, Some(rec)) => {
                            let ours = serde_json::to_value(&rec).unwrap();
                            same(&f, oracle, &ours, &format!("{name}:{label}"))
                                .unwrap_or_else(|e| panic!("record mismatch {e}"));
                        }
                        (o, u) => panic!("{name}:{label}: oracle null={o} ours={u:?}"),
                    }
                    compared += 1;
                }
            } else if let Some(arg) = qname
                .strip_prefix("getSage(")
                .and_then(|s| s.strip_suffix(')'))
            {
                let id = match arg {
                    "unknown" => "01UNKNOWNUNKNOWNUNKNOWN000".to_string(),
                    a if a.starts_with("01") => a.to_string(),
                    label => f.real_id(label),
                };
                let ours = f.store.get(&id, &viewer).unwrap();
                assert_eq!(
                    q["result"]["ok"].is_null(),
                    ours.is_none(),
                    "{name} {qname}"
                );
                compared += 1;
            }
        }
    }
    assert!(compared >= 10, "too few exact-ID comparisons: {compared}");
}

#[test]
fn path_retrieval_matches_oracle_sets() {
    let f = load("basic");
    let mut compared = 0;
    for q in &f.queries {
        let qname = q["name"].as_str().unwrap();
        let Some(rest) = qname.strip_prefix("retrieveForPath([") else {
            continue;
        };
        let (path, session) = match rest.split_once("]") {
            Some((p, tail)) => (
                p.to_string(),
                tail.split("sessionId=")
                    .nth(1)
                    .map(|s| s.trim_end_matches(')').to_string()),
            ),
            None => continue,
        };
        let ours = f
            .store
            .for_path(
                &path,
                50,
                &Viewer {
                    session_id: session,
                },
            )
            .unwrap();
        let ours: BTreeSet<String> = ours.hits.iter().map(|h| f.label(&h.memory.id)).collect();
        let want: BTreeSet<String> = ids_of(&f, q["result"]["ok"].as_array().unwrap())
            .into_iter()
            .collect();
        // retrieveForPath also follows graph relations; the slice's anchor
        // matching must at least return every directly anchored oracle hit
        // and nothing the oracle hides.
        assert!(
            ours == want,
            "{qname}: ours {ours:?} not within oracle {want:?}"
        );
        compared += 1;
    }
    assert!(compared >= 3);
}
